/// Write a file atomically using write-to-temp-then-rename.
///
/// Prevents corruption when multiple processes write the same file
/// concurrently — readers will never see a partially-written file.
fn atomic_write(path: &Path, content: &[u8]) -> Result<()> {
    let temp_path = path.with_extension("tmp");
    fs::write(&temp_path, content)
        .with_context(|| format!("Failed to write temp file {:?}", temp_path))?;
    fs::rename(&temp_path, path)
        .with_context(|| format!("Failed to rename {:?} to {:?}", temp_path, path))?;
    Ok(())
}

/// Atomically write content for a cache entry.
pub fn write_content(&self, source_id: &str, template_name: &str, content: &str) -> Result<()> {
    self.ensure_dir()?;
    let content_path = self.content_path(source_id, template_name);
    Self::atomic_write(&content_path, content.as_bytes())
}

/// Store content and return a cache entry.
pub fn store(
    &self,
    source_id: &str,
    template_name: &str,
    content: &str,
    ttl_seconds: u64,
) -> Result<CacheEntry> {
    self.ensure_dir()?;

    let content_path = self.content_path(source_id, template_name);
    // Write content atomically first, so metadata always refers to complete content
    Self::atomic_write(&content_path, content.as_bytes())?;

    let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
        .with_size(content.len() as u64);

    self.save_metadata(&entry)?;

    Ok(entry)
}

