/// Write a file atomically using write-to-temp-then-rename.
///
/// Prevents corruption when multiple processes write the same file
/// concurrently — readers will never see a partially-written file.
fn atomic_write(path: &Path, content: &[u8]) -> Result<()> {
    let temp_path = path.with_extension("tmp");
    fs::write(&temp_path, content)
        .with_context(|| format!("Failed to write temp file {:?}", temp_path))?;
    fs::rename(&temp_path, path)
        .with_context(|| format!("Failed to rename {:?} to {:?}", temp_path, path))?;
    Ok(())
}

input.new_string:
/// Write a file atomically using write-to-temp-then-rename.
///
/// Each call uses a unique temp file name (process ID + atomic counter)
/// so concurrent writers never clobber each other's temp files. Readers
/// will never see a partially-written file because `fs::rename` is atomic
/// on all supported platforms.
fn atomic_write(path: &Path, content: &[u8]) -> Result<()> {
    let id = TEMP_COUNTER.fetch_add(1, Ordering::Relaxed);
    let temp_path = path.with_extension(format!("tmp.{}.{}", std::process::id(), id));
    fs::write(&temp_path, content)
        .with_context(|| format!("Failed to write temp file {:?}", temp_path))?;
    if let Err(e) = fs::rename(&temp_path, path) {
        let _ = fs::remove_file(&temp_path);
        return Err(e)
            .with_context(|| format!("Failed to rename {:?} to {:?}", temp_path, path));
    }
    Ok(())
}

